#!/usr/bin/env node
// Task-local replica of the email-api skill's email-contacts.js helper.
// The registered helper cannot start because the 'minimist' npm package is
// not installed in the skill directory (MODULE_NOT_FOUND at require time).
// This script performs the identical documented request: GET /contacts with
// X-API-Key and X-User-Email headers, and prints the same JSON shape
// ({ success, count, contacts }), parsing --api-key/--user-email manually.

function parseArgs(argv) {
  const args = {};
  for (let i = 0; i < argv.length; i++) {
    const tok = argv[i];
    if (tok.startsWith('--')) {
      const key = tok.slice(2);
      const val = argv[i + 1];
      args[key] = val === undefined || val.startsWith('--') ? true : val;
      if (val !== undefined && !val.startsWith('--')) i++;
    }
  }
  return args;
}

const BASE_URL = process.env.EMAIL_API_BASE_URL || 'https://agenskill.onrender.com';

async function getContacts(args) {
  const apiKey = args['api-key'];
  const userEmail = args['user-email'];

  if (!apiKey || !userEmail) {
    throw new Error('Missing required arguments: --api-key and --user-email are required for authentication');
  }

  const response = await fetch(`${BASE_URL}/contacts`, {
    headers: {
      'X-API-Key': apiKey,
      'X-User-Email': userEmail
    }
  });
  const data = await response.json();

  if (!response.ok) {
    throw new Error(data.error || 'Failed to get contacts');
  }

  return {
    success: true,
    count: data.contacts ? data.contacts.length : 0,
    contacts: data.contacts || []
  };
}

const args = parseArgs(process.argv.slice(2));

getContacts(args)
  .then(result => {
    console.log(JSON.stringify(result, null, 2));
  })
  .catch(error => {
    console.error(JSON.stringify({ success: false, error: error.message }, null, 2));
    process.exit(1);
  });
